import React, {
  FormEvent,
  useCallback,
  useEffect,
  useMemo,
  useState,
} from 'react';

import { TEXT_SPIN_BUTTON_DEFAULTS } from '../constants.js';
import type { _TextSpinButtonProps } from '../types.js';

export const useValueNavigation = (props: _TextSpinButtonProps) => {
  // Set default keyboard behavior if undefined.
  const {
    values,
    onArrowUp = (idx, e) => {
      e.preventDefault();
      return idx - TEXT_SPIN_BUTTON_DEFAULTS.SMALL_STEP;
    },
    onArrowDown = (idx, e) => {
      e.preventDefault();
      return idx + TEXT_SPIN_BUTTON_DEFAULTS.SMALL_STEP;
    },
    onPageUp = (idx, e) => {
      e.preventDefault();
      return idx - TEXT_SPIN_BUTTON_DEFAULTS.BIG_STEP;
    },
    onPageDown = (idx, e) => {
      e.preventDefault();
      return idx + TEXT_SPIN_BUTTON_DEFAULTS.BIG_STEP;
    },
    onHome = (_, e) => {
      e.preventDefault();
      return 0;
    },
    onEnd = (_, e) => {
      e.preventDefault();
      return values.length - 1;
    },
    disabled,
    readonly,
    defaultValue = TEXT_SPIN_BUTTON_DEFAULTS.VALUE,
    value: valueProp,
    onChange,
  } = props;

  const [value, setValue] = useState(valueProp ?? defaultValue);

  // Update value to the result of the given tranform function.
  const handleValueNavigation = useCallback(
    (
      transform: (curIndex: number, e: FormEvent) => number,
      event: FormEvent,
    ) => {
      const sanitized = (idx: number) =>
        Math.min(values.length - 1, Math.max(0, idx));

      // if nothing was selected, start with the first configured value
      const curIndex = value === null ? 0 : values.indexOf(value);
      const newIndex = sanitized(transform(curIndex, event));
      const newValue = values[newIndex];

      if (value !== newValue) {
        setValue(newValue);
        onChange?.(newValue);
      }
    },
    [onChange, value, values],
  );

  // Lookup table for faster search
  const lookupTable = useMemo(
    () => values.map((v) => v[0].toLowerCase()),
    [values],
  );

  // For a given key, scan lookup table and update the value accordingly.
  const searchValue = useCallback(
    (key: string, fireOnChange = false) => {
      const idx = lookupTable.indexOf(key.toLowerCase());
      if (idx < 0) {
        return undefined;
      }

      const newValue = values[idx];
      if (value !== newValue) {
        setValue(newValue);
      }

      fireOnChange && onChange?.(newValue);

      return newValue;
    },
    [lookupTable, onChange, value, values],
  );

  const clearValue = useCallback(
    (fireOnChange = false) => {
      setValue(null);
      fireOnChange && onChange?.(null);
    },
    [onChange],
  );

  const keyDownHandler = useCallback(
    (e: React.KeyboardEvent) => {
      if (disabled || readonly) {
        // Prevent any value changes via keys, but don't prevent the default behavior.
        return;
      }
      switch (e.key) {
        case 'ArrowUp':
          handleValueNavigation(onArrowUp, e);
          break;
        case 'ArrowDown':
          handleValueNavigation(onArrowDown, e);
          break;
        case 'PageUp':
          handleValueNavigation(onPageUp, e);
          break;
        case 'PageDown':
          handleValueNavigation(onPageDown, e);
          break;
        case 'Home':
          handleValueNavigation(onHome, e);
          break;
        case 'End':
          handleValueNavigation(onEnd, e);
          break;
        case 'Backspace':
        case 'Delete':
          if (value !== null) {
            setValue(null);
            onChange?.(null);
          }
          e.preventDefault();
          break;
        default:
          // If a character key was pressed, look for a value starting with the char.
          if (!e.metaKey && !e.ctrlKey && e.key.match(/^\w$/)) {
            const newValue = searchValue(e.key);
            if (newValue !== undefined && newValue !== value) {
              onChange?.(newValue);
            }
            e.preventDefault();
          }
          break;
      }
    },
    [
      disabled,
      handleValueNavigation,
      onArrowDown,
      onArrowUp,
      onChange,
      onEnd,
      onHome,
      onPageDown,
      onPageUp,
      readonly,
      searchValue,
      value,
    ],
  );

  useEffect(() => {
    // update value if component is in controlled mode
    if (valueProp !== undefined) {
      setValue(valueProp);
    }
  }, [valueProp]);

  return { value, keyDownHandler, searchValue, clearValue };
};
